-- Catalog rows are visible only to authenticated users while the tenant module is enabled.
create policy subscription_plans_customer_select on public.subscription_plans
  for select to authenticated using (active and public.organization_module_enabled(organization_id, 'subscription_plans') and exists (select 1 from public.customers c where c.organization_id=public.subscription_plans.organization_id and c.auth_user_id=(select auth.uid()) and c.active and c.merged_into_customer_id is null));

create policy subscription_plan_versions_customer_select on public.subscription_plan_versions
  for select to authenticated using (exists (select 1 from public.subscription_plans p where p.id=public.subscription_plan_versions.plan_id and p.organization_id=public.subscription_plan_versions.organization_id and p.active and public.organization_module_enabled(p.organization_id, 'subscription_plans')) and exists (select 1 from public.customers c where c.organization_id=public.subscription_plan_versions.organization_id and c.auth_user_id=(select auth.uid()) and c.active and c.merged_into_customer_id is null));
create policy subscription_plan_services_customer_select on public.subscription_plan_services
  for select to authenticated using (exists (select 1 from public.subscription_plan_versions v join public.subscription_plans p on p.id=v.plan_id and p.organization_id=v.organization_id where v.id=public.subscription_plan_services.plan_version_id and v.organization_id=public.subscription_plan_services.organization_id and p.active and public.organization_module_enabled(v.organization_id, 'subscription_plans')) and exists (select 1 from public.customers c where c.organization_id=public.subscription_plan_services.organization_id and c.auth_user_id=(select auth.uid()) and c.active and c.merged_into_customer_id is null));
